// Separate reconstruction: PARI characters/primes and brute-force label masks.
#include <pari/pari.h>
#include <algorithm>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem;
static void check(bool b,const std::string& s){if(!b)throw std::runtime_error(s);}
static std::string read(const fs::path& p){std::ifstream f(p);check(bool(f),"read "+p.string());std::ostringstream s;s<<f.rdbuf();return s.str();}
static std::vector<std::string> cells(const std::string& s){std::vector<std::string> v;std::istringstream f(s);std::string x;while(std::getline(f,x,'\t'))v.push_back(x);return v;}
struct Curve{std::string id,run;int bits;bool pub;GEN disc;};
using Grid=std::vector<std::vector<int>>;
static int margin(uint32_t m,const Grid& c,size_t j,const std::vector<Curve>& r,int bits){int out=10000;bool paired=false;for(size_t a=0;a<r.size();++a)if(r[a].bits==bits&&(m&(uint32_t(1)<<a)))for(size_t b=0;b<r.size();++b)if(r[b].bits==bits&&!(m&(uint32_t(1)<<b))){paired=true;out=std::min(out,c[b][j]-c[a][j]);}return paired?out:10000;}
static bool fits(uint32_t m,const Grid& c,size_t j,const std::vector<Curve>& r){for(const auto& q:r)if(margin(m,c,j,r,q.bits)<=0)return false;return true;}
int main(int argc,char** argv){try{pari_init(128000000,1000000);if(argc==2&&std::string(argv[1])=="--self-test"){check(kronecker(stoi(9),stoi(11))==1&&kronecker(stoi(3),stoi(5))==-1&&kronecker(gen_0,stoi(7))==0,"three character controls");check(uisprime(4999)&&!uisprime(5000),"upper cutoff boundary");std::cout<<"PASS:PARI positive/negative/zero characters and upper prime boundary\n";return 0;}check(argc==4,"verify_sweep COHORT RESULTS NEW_RECEIPT");std::istringstream in(read(argv[1]));std::vector<Curve> rows;std::map<std::string,std::pair<uint32_t,int>> groups;std::string line;uint32_t actual=0;while(std::getline(in,line)){if(line.empty()||line[0]=='#')continue;auto c=cells(line);check(c.size()==9,"columns");Curve r;r.id=c[0];r.bits=std::stoi(c[1]);r.run=c[3];check(c[2]=="published"||c[2]=="skipped","role");r.pub=c[2]=="published";GEN p=gp_read_str(c[5].c_str()),n=gp_read_str(c[7].c_str()),t=subii(addis(p,1),n);r.disc=subii(sqri(t),shifti(p,2));check(signe(r.disc)<0,"discriminant");uint32_t bit=uint32_t(1)<<rows.size();auto& g=groups[r.run];g.first|=bit;g.second+=r.pub;if(r.pub)actual|=bit;rows.push_back(r);}check(rows.size()==21&&__builtin_popcount(actual)==10,"all21 rows");std::vector<int> primes;for(int n=2;n<=5000;++n)if(uisprime(static_cast<ulong>(n)))primes.push_back(n);check(primes.size()==669,"prime count");auto col=[&](int cutoff){size_t j=0;while(j+1<primes.size()&&primes[j+1]<=cutoff)++j;return j;};Grid a(21,std::vector<int>(669)),z=a,b=a;std::ostringstream chars;chars<<"label\tell\tcharacter\tstrict\tramified\tinclusive\n";for(size_t j=0;j<669;++j)for(size_t i=0;i<21;++i){if(j){a[i][j]=a[i][j-1];z[i][j]=z[i][j-1];b[i][j]=b[i][j-1];}if(j==0){chars<<rows[i].id<<"\t2\tNA_ell2\t0\t0\t0\n";continue;}pari_sp saved=avma;long ch=kronecker(rows[i].disc,stoi(primes[j]));avma=saved;a[i][j]+=ch==1;z[i][j]+=ch==0;b[i][j]+=ch>=0;chars<<rows[i].id<<'\t'<<primes[j]<<'\t'<<ch<<'\t'<<a[i][j]<<'\t'<<z[i][j]<<'\t'<<b[i][j]<<'\n';}
 std::ostringstream profiles,cut,cal;profiles<<"label\tbits\trole\tcutoff\tstrict\tramified\tinclusive\n";cut<<"cutoff\tstrict_separates\tinclusive_separates\tmargin192\tmargin224\tmargin239\tmargin256\n";std::vector<std::pair<int,int>> intervals;int first=-1;for(int L=100;L<=5000;++L){size_t j=col(L);bool ok=fits(actual,a,j,rows);if(ok&&first<0)first=L;if(!ok&&first>=0){intervals.emplace_back(first,L-1);first=-1;}cut<<L<<'\t'<<ok<<'\t'<<fits(actual,b,j,rows);for(int bits:{192,224,239,256})cut<<'\t'<<margin(actual,a,j,rows,bits);cut<<'\n';for(size_t i=0;i<21;++i)profiles<<rows[i].id<<'\t'<<rows[i].bits<<'\t'<<(rows[i].pub?"published":"skipped")<<'\t'<<L<<'\t'<<a[i][j]<<'\t'<<z[i][j]<<'\t'<<b[i][j]<<'\n';}if(first>=0)intervals.emplace_back(first,5000);
 int total=0,good=0,inc=0,fixed=0,old=0;cal<<"published_mask\tstrict_any_100_5000\tstrict_fixed691\tinclusive_any_100_5000\tstrict_any_2_2000\n";for(uint32_t m=0;m<(uint32_t(1)<<21);++m){bool valid=true;for(const auto& g:groups)if(__builtin_popcount(m&g.second.first)!=g.second.second){valid=false;break;}if(!valid)continue;++total;bool any=fits(m,a,col(100),rows),inclusive=fits(m,b,col(100),rows),prior=false;for(size_t j=0;j<primes.size();++j){if(primes[j]>100){any=any||fits(m,a,j,rows);inclusive=inclusive||fits(m,b,j,rows);}if(primes[j]<=2000)prior=prior||fits(m,a,j,rows);}bool one=fits(m,a,col(691),rows);good+=any;inc+=inclusive;fixed+=one;old+=prior;cal<<m<<'\t'<<any<<'\t'<<one<<'\t'<<inclusive<<'\t'<<prior<<'\n';}check(total==4480&&fixed==1&&old==23,"fixed/previous calibration");std::ostringstream summary;summary<<"{\"kind\":\"retrospective-cutoff-sweep-100-5000/v1\",\"rows\":21,\"integer_cutoffs\":4901,\"effective_cutoffs\":645,\"odd_prime_character_cells\":14028,\"label_assignments\":4480,\"strict_search_success_assignments\":"<<good<<",\"inclusive_search_success_assignments\":"<<inc<<",\"strict_fixed691_success_assignments\":"<<fixed<<",\"previous_search_success_assignments\":"<<old<<",\"strict_integer_success_intervals\":[";for(size_t i=0;i<intervals.size();++i){if(i)summary<<',';summary<<'['<<intervals[i].first<<','<<intervals[i].second<<']';}summary<<"],\"historical_use_established\":false,\"independent_verification_pending\":true}\n";fs::path result=argv[2];for(const auto& item:std::vector<std::pair<std::string,std::string>>{{"characters.tsv",chars.str()},{"profiles.tsv",profiles.str()},{"cutoffs.tsv",cut.str()},{"calibration.tsv",cal.str()},{"summary.json",summary.str()}})check(read(result/item.first)==item.second,"independent mismatch: "+item.first);check(!fs::exists(argv[3]),"fresh receipt");std::ofstream receipt(argv[3]);check(bool(receipt),"receipt creation");receipt<<"{\"kind\":\"independent-pari-sweep-verification/v1\",\"rows\":21,\"integer_cutoffs\":4901,\"character_cells\":14028,\"label_assignments\":4480,\"all_five_files_equal\":true,\"shared_integer_library_family\":\"GMP\",\"historical_use_established\":false}\n";check(bool(receipt),"receipt write");std::cout<<"PASS:reconstructed all five files,14028characters,4901cutoffs and4480labels\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
